properties.query:
let alertWindow = 15m;
let battThreshold = 15;
let SuppressEvent =
    UAVFailsafe_CL
    | where TimeGenerated > ago(alertWindow)
    | where Text has_any ("Arming Checks Disabled", "failsafe", "GCS Failsafe")
    | project T_suppress=TimeGenerated, UAVId, Text;
let BattLow =
    UAVTelemetry_CL
    | where TimeGenerated > ago(alertWindow)
    | where MsgType == 'SYS_STATUS'
    | where BatteryRemaining_pct < battThreshold
    | summarize LowCount=count(), MinBatt=min(BatteryRemaining_pct) by UAVId;
SuppressEvent
| join kind=inner (BattLow) on UAVId
| extend TriggerReason = strcat("Failsafe_억제_배터리_", tostring(MinBatt), "%_이하_Text:", Text)
| extend Severity = "High"
| project T_suppress, UAVId, Text, LowCount, MinBatt, TriggerReason, Severity
| order by T_suppress desc
